// TEST-ONLY harness: visualise Titan rig + boulders at several times
const logEl = document.createElement('pre');
logEl.style.cssText = 'position:fixed;left:0;top:0;margin:0;color:#0f0;background:rgba(0,0,0,.6);font:11px monospace;z-index:999;max-width:100vw;white-space:pre-wrap';
document.body.appendChild(logEl);
const log = (s) => { logEl.textContent += s + '\n'; };
window.addEventListener('error', (e) => log('ERR ' + e.message + ' @' + e.lineno));
try {
  const t0 = performance.now();
  buildBoulders();
  log('boulders ' + boulders.length + ' build ms ' + (performance.now() - t0).toFixed(1));
  const cnt = {}; boulders.forEach((b) => (cnt[b.bone] = (cnt[b.bone] || 0) + 1)); log('per bone ' + JSON.stringify(cnt));
  const t1 = performance.now(); precomputeCollapse(); precomputeWpFall(); log('collapse ms ' + (performance.now() - t1).toFixed(1));
  const t2 = performance.now(); for (let i = 0; i < 1000; i++) titanPose(i * 0.04, makeTitanPose()); log('1000 poses ms ' + (performance.now() - t2).toFixed(1));
  const W = 640, H = 360;
  const canvas = document.getElementById('stage');
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
  renderer.setSize(W, H, false);
  const scene = new THREE.Scene(); scene.background = new THREE.Color(0x404858);
  scene.add(new THREE.HemisphereLight(0xaabbcc, 0x334422, 0.7));
  const dl = new THREE.DirectionalLight(0xffffff, 0.8); dl.position.set(-50, 80, -30); scene.add(dl);
  const gnd = new THREE.Mesh(new THREE.PlaneGeometry(200, 200, 20, 20), new THREE.MeshLambertMaterial({ color: 0x3a5a30 }));
  gnd.rotation.x = -Math.PI / 2; scene.add(gnd);
  const grid = new THREE.GridHelper(200, 20, 0x222222, 0x555555); grid.position.y = 0.05; scene.add(grid);
  const im = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(0.5, 1), new THREE.MeshLambertMaterial({ color: 0x777777 }), boulders.length);
  scene.add(im);
  const lineGeo = new THREE.BufferGeometry(); const lp = new Float32Array(NB * 6); lineGeo.setAttribute('position', new THREE.BufferAttribute(lp, 3));
  const lines = new THREE.LineSegments(lineGeo, new THREE.LineBasicMaterial({ color: 0xff3300 })); scene.add(lines);
  const wpm = []; for (let i = 0; i < 3; i++) { const s = new THREE.Mesh(new THREE.SphereGeometry(0.6, 12, 8), new THREE.MeshBasicMaterial({ color: 0xffaa00 })); scene.add(s); wpm.push(s); }
  const mark = new THREE.Mesh(new THREE.SphereGeometry(0.5, 8, 6), new THREE.MeshBasicMaterial({ color: 0x00ffff })); scene.add(mark);
  const cam = new THREE.PerspectiveCamera(45, W / H, 0.1, 2000);
  const times = (location.hash.slice(1) || '0,2,4,7.1,7.5,10,12,13,15.5,18.5,19,19.3').split(',').map(Number);
  const views = [[-60, 20, -45], [-40, 15, 40]];
  const out = document.createElement('div'); out.style.cssText = 'position:fixed;left:0;top:0;width:100vw;display:flex;flex-wrap:wrap;background:#000'; document.body.appendChild(out);
  const pos = new V3(), q = new Q(), mat = new THREE.Matrix4(), sc = new V3();
  for (const m of times) {
    const pose = titanPose(m, makeTitanPose());
    boulders.forEach((bd, i) => { boulderAt(bd, m, pose, pos, q); mat.compose(pos, q, bd.scale); im.setMatrixAt(i, mat); });
    im.instanceMatrix.needsUpdate = true;
    pose.bones.forEach((b, i) => { lp.set([b.o.x, b.o.y, b.o.z, b.e.x, b.e.y, b.e.z], i * 6); });
    lineGeo.attributes.position.needsUpdate = true;
    for (let i = 0; i < 3; i++) wpAt(i, m, pose, wpm[i].position);
    mark.position.copy(P65);
    const v = views[m > 16 ? 1 : 0];
    cam.position.set(v[0], v[1], v[2]); cam.lookAt(16, 14, 0);
    renderer.render(scene, cam);
    const img = new Image(); img.src = canvas.toDataURL(); img.style.width = '33.3vw'; img.title = m; out.appendChild(img);
    const fist = pose.bones[B.LFI].e, rf = pose.bones[B.RFI].e;
    log('m=' + m + ' LFIe ' + fist.x.toFixed(1) + ',' + fist.y.toFixed(1) + ',' + fist.z.toFixed(1) + ' RFIe ' + rf.x.toFixed(1) + ',' + rf.y.toFixed(1) + ',' + rf.z.toFixed(1) + ' head ' + pose.bones[B.HEAD].e.y.toFixed(1) + ' RUAo ' + pose.bones[B.RUA].o.x.toFixed(1) + ',' + pose.bones[B.RUA].o.y.toFixed(1) + ',' + pose.bones[B.RUA].o.z.toFixed(1) + ' LSHo(knee) ' + pose.bones[B.LSH].o.x.toFixed(1) + ',' + pose.bones[B.LSH].o.y.toFixed(1) + ',' + pose.bones[B.LSH].o.z.toFixed(1));
  }
  document.body.appendChild(logEl);
} catch (e) { log('EXC ' + e.message + '\n' + e.stack); }

