// ============================================================================
// 9a. BOULDER MESHES (instanced, wet basalt + blue ore veins), WEAK POINTS,
//     BINDING LIGHTNING ARCS (ribbons), SKY BOLTS
// ============================================================================
const wetU = { uWet: { value: 0 } };
function makeRockGeometry(seed) {
  const g = new THREE.SphereGeometry(0.5, 26, 18);
  const r = mulberry32(seed);
  const planes = [];
  for (let k = 0; k < 7; k++) { const n = new V3(r() - 0.5, r() - 0.5, r() - 0.5).normalize(); planes.push([n, 0.3 + r() * 0.14]); }
  const off = [r() * 50, r() * 50, r() * 50];
  const pos = g.attributes.position, v = new V3();
  const n3 = (x, y, z) => Math.sin(x * 1.7 + off[0]) * Math.sin(y * 2.3 + off[1]) * Math.sin(z * 1.9 + off[2]);
  let maxR = 0;
  for (let i = 0; i < pos.count; i++) {
    v.fromBufferAttribute(pos, i);
    const d = v.clone().normalize();
    let rad = 0.5 * (1 + 0.16 * n3(d.x * 3, d.y * 3, d.z * 3) + 0.07 * n3(d.x * 9 + 3, d.y * 9, d.z * 9 - 2));
    v.copy(d).multiplyScalar(rad);
    for (const [pn, pd] of planes) { const s = v.dot(pn); if (s > pd) v.addScaledVector(pn, -(s - pd) * 0.88); }
    pos.setXYZ(i, v.x, v.y, v.z);
    maxR = Math.max(maxR, v.length());
  }
  for (let i = 0; i < pos.count; i++) { v.fromBufferAttribute(pos, i).multiplyScalar(0.5 / maxR); pos.setXYZ(i, v.x, v.y, v.z); }
  g.computeVertexNormals();
  return g;
}
const rockMat = new THREE.MeshStandardMaterial({ color: lin(0x34363a), roughness: 0.9, metalness: 0.0, envMapIntensity: 0.9 });
rockMat.onBeforeCompile = (sh) => {
  sh.uniforms.uWet = wetU.uWet;
  sh.vertexShader = sh.vertexShader.replace('#include <common>', `#include <common>
    attribute float aGlow; attribute float aDead; attribute float aSeedB; varying vec3 vRP; varying float vGlow; varying float vDead;`)
    .replace('#include <begin_vertex>', `#include <begin_vertex>
    vRP = position * 2.2 + vec3(aSeedB * 17.0, aSeedB * 5.0, -aSeedB * 11.0); vGlow = aGlow; vDead = aDead;`);
  sh.fragmentShader = sh.fragmentShader.replace('#include <common>', `#include <common>
    uniform float uWet; varying vec3 vRP; varying float vGlow; varying float vDead;
    ` + GLSL_NOISE + `float gCrack; float gVein;`)
    .replace('#include <color_fragment>', `#include <color_fragment>
    { float n1 = vnoise3(vRP * 1.25); float n2 = vnoise3(vRP * 2.7 + 5.0); float n3 = vnoise3(vRP * 7.0);
      gCrack = 1.0 - smoothstep(0.0, 0.05, abs(n1 - 0.5));
      gVein = (1.0 - smoothstep(0.0, 0.035, abs(n2 - 0.52))) * smoothstep(0.35, 0.6, vnoise3(vRP * 0.6 + 9.0));
      diffuseColor.rgb *= (1.0 - 0.6 * gCrack) * (0.72 + 0.5 * n3);
      diffuseColor.rgb *= 1.0 - 0.5 * uWet * (1.0 - gCrack * 0.5); }`)
    .replace('#include <roughnessmap_fragment>', `#include <roughnessmap_fragment>
    roughnessFactor = clamp(roughnessFactor + gCrack * 0.25 - 0.1 * (vnoise3(vRP * 3.0) - 0.5), 0.05, 1.0);`)
    .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
    totalEmissiveRadiance += vec3(0.22, 0.48, 1.0) * (gVein * (0.05 + 2.4 * vGlow) + gCrack * 0.35 * vGlow) * (1.0 - vDead);`);
};
const ROCK_SHAPES = 4;
const rockGeos = [], rockMeshes = [], rockIdx = []; // per shape list of boulder indices
function buildBoulderMeshes() {
  for (let s = 0; s < ROCK_SHAPES; s++) rockIdx.push([]);
  boulders.forEach((b, i) => rockIdx[b.shape].push(i));
  for (let s = 0; s < ROCK_SHAPES; s++) {
    const g = makeRockGeometry(SEED * 100 + s * 17);
    const n = Math.max(1, rockIdx[s].length);
    g.setAttribute('aGlow', new THREE.InstancedBufferAttribute(new Float32Array(n), 1));
    g.setAttribute('aDead', new THREE.InstancedBufferAttribute(new Float32Array(n), 1));
    const sd = new Float32Array(n); rockIdx[s].forEach((bi, k) => (sd[k] = (boulders[bi].seed % 1000) / 1000));
    g.setAttribute('aSeedB', new THREE.InstancedBufferAttribute(sd, 1));
    const mesh = new THREE.InstancedMesh(g, rockMat, n);
    mesh.castShadow = true; mesh.receiveShadow = true; mesh.frustumCulled = false;
    mesh.count = rockIdx[s].length;
    rockGeos.push(g); rockMeshes.push(mesh); scene.add(mesh);
  }
}
const _bm = new THREE.Matrix4(), _bp = new V3(), _bqq = new Q();
const bPos = []; // current world positions of boulders (for arcs)
function updateBoulders(m, s, pose, glowArr) {
  for (let sh = 0; sh < ROCK_SHAPES; sh++) {
    const mesh = rockMeshes[sh], ids = rockIdx[sh];
    const ga = rockGeos[sh].attributes.aGlow, da = rockGeos[sh].attributes.aDead;
    for (let k = 0; k < ids.length; k++) {
      const bi = ids[k], bd = boulders[bi];
      boulderAt(bd, m, pose, _bp, _bqq);
      bPos[bi].copy(_bp);
      _bm.compose(_bp, _bqq, bd.scale);
      mesh.setMatrixAt(k, _bm);
      ga.array[k] = glowArr[bi];
      const rel = BONE_REL_SIM[bd.bone];
      da.array[k] = sstep(rel, rel + 2.5, s) * 0.85 + 0.15 * sstep(36, 39.5, s);
    }
