// ---------------- weak points ----------------
function radialTex(stops) {
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const g = c.getContext('2d'); const gr = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  stops.forEach(([o, col]) => gr.addColorStop(o, col)); g.fillStyle = gr; g.fillRect(0, 0, 128, 128);
  const t = new THREE.CanvasTexture(c); return t;
}
const glowTex = radialTex([[0, 'rgba(255,255,255,1)'], [0.2, 'rgba(255,255,255,0.6)'], [0.5, 'rgba(255,255,255,0.15)'], [1, 'rgba(255,255,255,0)']]);
const wpMeshes = WP.map(() => {
  const mat = new THREE.MeshStandardMaterial({ color: lin(0x241a10), emissive: new THREE.Color(1, 0.55, 0.12), emissiveIntensity: 2.5, roughness: 0.3, metalness: 0.1 });
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.6, 28, 18), mat);
  const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex, color: 0xffa040, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, fog: true }));
  sp.scale.set(4.5, 4.5, 1);
  scene.add(mesh); scene.add(sp);
  return { mesh, mat, sp };
});

// ---------------- ribbon shader (arcs, bolts, tethers) ----------------
function ribbonMaterial(core, glow, width, opts) {
  return new THREE.ShaderMaterial({
    uniforms: { uCore: { value: core }, uGlow: { value: glow }, uWidth: { value: width }, uFogD: { value: 0.0068 }, uGain: { value: 1 }, uFogK: { value: (opts && opts.fogK) || 1 } },
    transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
    vertexShader: `attribute vec3 aOther; attribute float aSide; attribute float aEnd; attribute float aInt;
      uniform float uWidth, uFogD, uFogK; varying float vSide; varying float vInt; varying float vFog;
      void main(){
        vec4 pv = modelViewMatrix * vec4(position, 1.0);
