  logEl.style.cssText = 'position:fixed;left:0;bottom:0;margin:0;color:#0f0;background:rgba(0,0,0,.75);font:12px monospace;z-index:9999;max-width:100vw;max-height:45vh;overflow:hidden;white-space:pre-wrap';
  const log = (s) => { logEl.textContent += s + '\n'; };
  const errs = window.__errs || [];
  log('init+boot ms ' + (performance.now() - (window.__t0 || 0)).toFixed(0));
  if (errs.length) log('ERRORS: ' + errs.join(' | '));
  const hash = decodeURIComponent(location.hash.slice(1) || '');
  const parts = hash.split('|');
  const times = (parts[0] || '0,3.5,4.6,5.0,7.6,8.2,11,12,13.2').split(',').map(Number);
  const cols = parseInt(parts[1] || '3', 10);
  const info = parts[2] || '';
  try {
    if (!window.__storm) { log('NO __storm (main script failed)'); document.body.appendChild(logEl); return; }
    const grid = document.createElement('div');
    grid.style.cssText = 'position:fixed;left:0;top:0;width:100vw;display:flex;flex-wrap:wrap;background:#000;z-index:9000';
    document.body.appendChild(grid);
    const canvas = document.getElementById('stage');
    for (const t of times) {
      const t0 = performance.now();
      const r = window.__storm.renderAt(t);
      const dt = performance.now() - t0;
      const img = new Image(); img.src = canvas.toDataURL('image/jpeg', 0.85); img.style.width = (100 / cols) + 'vw'; grid.appendChild(img);
      const H = window.__storm.hunter(t);
      log('t=' + t + ' ms=' + dt.toFixed(1) + ' arcs=' + r.arcs + ' shot=' + r.cam.shot + ' fov=' + r.cam.fov.toFixed(1) + (r.cam.fovExtra ? '(+' + r.cam.fovExtra + ')' : '') + ' cam=' + r.cam.pos.x.toFixed(1) + ',' + r.cam.pos.y.toFixed(1) + ',' + r.cam.pos.z.toFixed(1) +
        ' H=' + H.root.x.toFixed(1) + ',' + H.root.y.toFixed(1) + ',' + H.root.z.toFixed(1) + ' ' + H.kind + ' v=' + H.speed.toFixed(1));
    }
    if (info) {
      const S = window.__storm;
      log('P65 ' + JSON.stringify(S.P65()) + ' P0 ' + JSON.stringify(S.P0()) + ' FALL1 tLand ' + S.FALL1().tLand.toFixed(3));
      log('thumps ' + S.ragThumps().map((x) => x.t.toFixed(2)).join(','));
      log('getup low ' + JSON.stringify(S.GETUP().lowPos) + ' stand ' + JSON.stringify(S.GETUP().standPos));
    }
    if (window.__errs.length > errs.length) log('LATER ERRORS: ' + window.__errs.slice(errs.length).join(' | '));
  } catch (e) { log('EXC ' + e.message + '\n' + e.stack); }
  document.body.appendChild(logEl);
})();

