    const cb = D.rockMat.onBeforeCompile; D.rockMat.onBeforeCompile = () => {}; D.rockMat.needsUpdate = true; S.renderAt(2.0); shot('C rock plain'); D.rockMat.onBeforeCompile = cb; D.rockMat.needsUpdate = true;
    D.arcMat.blending = THREE.NormalBlending; D.arcMat.needsUpdate = true; S.renderAt(2.0); shot('D arcs normal blend, arcBuf.n=' + D.arcBuf.n);
    D.arcMat.blending = THREE.AdditiveBlending; D.arcMat.needsUpdate = true;
    D.keyLight.castShadow = false; S.renderAt(2.0); shot('E no shadows');
    D.keyLight.castShadow = true;
    log('glErr ' + gl.getError() + ' envTex ' + (D.envTex && D.envTex.image ? JSON.stringify([D.envTex.image.width, D.envTex.image.height]) : 'n/a'));
