(function () {
  const logEl = document.createElement('pre');
  logEl.style.cssText = 'position:fixed;left:0;bottom:0;margin:0;color:#0f0;background:rgba(0,0,0,.75);font:12px monospace;z-index:9999;max-width:100vw;white-space:pre-wrap';
  const log = (s) => { logEl.textContent += s + '\n'; };
  const grid = document.createElement('div');
  grid.style.cssText = 'position:fixed;left:0;top:0;width:100vw;display:flex;flex-wrap:wrap;background:#000;z-index:9000';
  document.body.appendChild(grid);
  const canvas = document.getElementById('stage');
  const S = window.__storm, D = S.dbg();
  const shot = (label) => { const img = new Image(); img.src = canvas.toDataURL('image/jpeg', 0.85); img.style.width = '50vw'; grid.appendChild(img); log(label); };
  try {
    S.renderAt(4.6);
    const cam = D.camera;
    // test ribbon 6 m in front of camera
    const mat = D.ribbonMaterial(new THREE.Color(3, 0.2, 0.2), new THREE.Color(0.3, 1, 0.3), 0.3);
    const rb = new D.RibbonBuffer(4, mat);
    const f = new THREE.Vector3(0, 0, -1).applyQuaternion(cam.quaternion), r = new THREE.Vector3(1, 0, 0).applyQuaternion(cam.quaternion);
    const a = cam.position.clone().addScaledVector(f, 6).addScaledVector(r, -2), b = cam.position.clone().addScaledVector(f, 6).addScaledVector(r, 2);
    rb.begin(); rb.seg(a.x, a.y, a.z, b.x, b.y, b.z, 1, 1); rb.end_();
    D.scene.add(rb.mesh);
    S.renderAt(4.6); shot('test ribbon red/green across view; arcBuf.n=' + D.arcBuf.n + ' arc drawRange=' + JSON.stringify(D.arcBuf.geo.drawRange) + ' rope0 vis=' + D.ropeBufs[0].mesh.visible + ' n=' + D.ropeBufs[0].n);
    const p = D.arcBuf.pos; log('arc first pts ' + Array.from(p.slice(0, 12)).map((x) => x.toFixed(1)).join(','));
    const rp = D.ropeBufs[0].pos; log('rope first pts ' + Array.from(rp.slice(0, 12)).map((x) => x.toFixed(2)).join(',') + ' cam ' + cam.position.toArray().map((x) => x.toFixed(1)));
    log('arc int ' + Array.from(D.arcBuf.int.slice(0, 8)).map((x) => x.toFixed(2)).join(','));
    D.arcMat.uniforms.uWidth.value = 2.5; D.arcMat.blending = THREE.NormalBlending; D.arcMat.needsUpdate = true;
    S.renderAt(4.6); shot('arcs wide normal');
    log('console: ' + (window.__cons || []).join('\n'));
  } catch (e) { log('EXC ' + e.message + '\n' + e.stack); }
  document.body.appendChild(logEl);
})();

