import os
base=os.path.join(os.environ['TMPDIR'],'stormtest/parts/')
def rep(f,a,b,cnt=1):
  p=base+f; s=open(p).read()
  assert s.count(a)==cnt, (f,a[:60],s.count(a))
  s=s.replace(a,b); open(p,'w').write(s)
# a+b camera
rep('p06_camera.js','''      _cD.y = clamp(_cD.y, -0.45, 0.55); _cD.normalize();''','''      _cD.y = clamp(_cD.y, -0.3, 0.1); _cD.normalize();''')
rep('p06_camera.js','''  const gmin = groundH(P.x, P.z) + 0.45;
  if (P.y < gmin) P.y = gmin;''','''  if (shot === 1 || shot === 4) pushOutOfTitan(P, tpose, m);
  const gmin = groundH(P.x, P.z) + (shot === 3 ? 0.45 : 1.2);
  if (P.y < gmin) P.y = gmin;''')
rep('p06_camera.js','''function computeCamera(s, aspect) {''','''// keep follow cameras outside the Titan's bone capsules (closed form, a few relaxation passes)
function pushOutOfTitan(P, pose, m) {
  for (let it = 0; it < 3; it++) {
    for (let b = 0; b < NB; b++) {
      if (m >= BONE_REL_M[b]) continue;
      const bn = pose.bones[b];
      _cA.subVectors(P, bn.o);
