import http.server, socketserver, time, os, sys, urllib.parse
D = os.path.join(os.environ['TMPDIR'], 'stormtest')
GIF = b'GIF89a\x01\x00\x01\x00\x80\x00\x00\x00\x00\x00\xff\xff\xff!\xf9\x04\x01\x00\x00\x00\x00,\x00\x00\x00\x00\x01\x00\x01\x00\x00\x02\x02D\x01\x00;'
class H(http.server.SimpleHTTPRequestHandler):
    def __init__(self, *a, **k):
        super().__init__(*a, directory=D, **k)
    def log_message(self, *a):
        pass
    def do_GET(self):
        u = urllib.parse.urlparse(self.path)
        if u.path == '/delay':
            q = urllib.parse.parse_qs(u.query)
            time.sleep(int(q.get('ms', ['1000'])[0]) / 1000.0)
            self.send_response(200); self.send_header('Content-Type', 'image/gif'); self.send_header('Cache-Control', 'no-store'); self.end_headers(); self.wfile.write(GIF)
            return
        return super().do_GET()
class TS(socketserver.ThreadingMixIn, socketserver.TCPServer):
    allow_reuse_address = True
    daemon_threads = True
port = int(sys.argv[1]) if len(sys.argv) > 1 else 8765
with TS(('127.0.0.1', port), H) as s:
    s.serve_forever()

