(function () {
  const out = document.createElement('pre');
  out.style.cssText = 'position:fixed;left:0;top:0;margin:0;color:#0f0;background:rgba(0,0,0,.8);font:16px monospace;z-index:99999;white-space:pre-wrap';
  const img = new Image(); img.src = '/delay?ms=' + (parseInt((location.hash.slice(1) || '14000'), 10)); img.style.cssText = 'position:fixed;width:1px;height:1px;opacity:0'; document.body.appendChild(img);
  const frames = []; let last = null; const t0 = performance.now();
  const states = [];
  function tick(now) {
    if (last !== null) frames.push({ dt: now - last, st: window.__storm ? window.__storm.info().state : '?', sim: window.__storm ? window.__storm.info().simTime : 0 });
    last = now;
    if (now - t0 < (parseInt((location.hash.slice(1) || '14000'), 10) - 1500)) requestAnimationFrame(tick);
    else report();
  }
  requestAnimationFrame(tick);
  function report() {
    const play = frames.filter((f) => f.st === 'PLAYING');
    const dts = play.map((f) => f.dt).sort((a, b) => a - b);
    const avg = dts.reduce((a, b) => a + b, 0) / Math.max(1, dts.length);
    const p95 = dts[Math.floor(dts.length * 0.95)] || 0, p50 = dts[Math.floor(dts.length * 0.5)] || 0;
    const info = window.__storm ? window.__storm.info() : {};
    const lines = [];
    lines.push('frames total ' + frames.length + ' playing ' + play.length);
    lines.push('avg dt ' + avg.toFixed(2) + ' ms  => ' + (1000 / avg).toFixed(1) + ' fps; p50 ' + p50.toFixed(1) + ' p95 ' + p95.toFixed(1) + ' max ' + (dts[dts.length - 1] || 0).toFixed(1));
    lines.push('state ' + info.state + ' simTime ' + (info.simTime || 0).toFixed(3) + ' audio ' + JSON.stringify(info.audio || null));
    const cd = []; let prev = ''; frames.forEach((f) => { if (f.st !== prev) { cd.push(f.st + '@' + f.sim.toFixed(2)); prev = f.st; } });
    lines.push('state seq ' + cd.join(' -> '));
    lines.push('errors ' + (window.__errs || []).join(' | '));
    lines.push('console ' + (window.__cons || []).filter((c) => c.indexOf('not read by fragment') < 0).join('\n'));
    lines.push('countdown el: display=' + document.getElementById('countdown').style.display + ' text="' + document.getElementById('countdown').textContent + '" scrubber=' + document.getElementById('scrubber').value);
    out.textContent = lines.join('\n');
    document.body.appendChild(out);
  }
})();

