(function () {
  const logEl = document.createElement('pre');
  logEl.style.cssText = 'position:fixed;left:0;top:0;margin:0;color:#0f0;background:rgba(0,0,0,.85);font:16px monospace;z-index:9999;white-space:pre-wrap';
  const log = (s) => { logEl.textContent += s + '\n'; };
  try {
    const S = window.__storm, D = S.dbg();
    const counts = new Array(16).fill(0);
    D.rockMeshes.forEach(() => {});
    const bl = S.boulders();
    bl.forEach((b) => counts[b.bone]++);
    log('per-bone counts: ' + counts.join(','));
    log('min ' + Math.min(...counts) + ' max ' + Math.max(...counts) + ' total ' + bl.length);
    let mn = 99, mx = 0; bl.forEach((b) => { mn = Math.min(mn, b.size); mx = Math.max(mx, b.size); });
    log('size range ' + mn.toFixed(2) + '..' + mx.toFixed(2));
    // closest pair distance in rest pose minus radii (positive = gap)
    log('errors: ' + (window.__errs || []).join(' | '));
  } catch (e) { log('EXC ' + e.message + '\n' + e.stack); }
  document.body.appendChild(logEl);
})();

