  const logEl = document.createElement('pre');
  logEl.style.cssText = 'position:fixed;left:0;top:0;margin:0;color:#0f0;background:rgba(0,0,0,.85);font:16px monospace;z-index:9999;max-width:100vw;white-space:pre-wrap';
  const log = (s) => { logEl.textContent += s + '\n'; };
  const S = window.__storm, D = S.dbg();
  const gl = D.renderer.getContext();
  function hashFrame(t) {
    S.renderAt(t);
    const w = gl.drawingBufferWidth, h = gl.drawingBufferHeight;
    const px = new Uint8Array(w * h * 4);
    gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, px);
    let hsh = 2166136261 >>> 0;
    for (let i = 0; i < px.length; i += 7) { hsh ^= px[i]; hsh = Math.imul(hsh, 16777619) >>> 0; }
    return hsh.toString(16) + ' (' + w + 'x' + h + ')';
  }
  try {
    const order1 = [27.3, 4.4, 10.1, 30.9, 19.7];
    const a = order1.map((t) => [t, hashFrame(t)]);
    const order2 = [35, 30.9, 2, 19.7, 10.1, 4.4, 27.3, 12.2];
    const b = {}; order2.forEach((t) => (b[t] = hashFrame(t)));
    a.forEach(([t, h]) => log('t=' + t + ' first ' + h + ' second ' + b[t] + (h === b[t] ? '  MATCH' : '  DIFF')));
